// Extrae la respuesta JSON del modelo (OpenAI Chat).
const choice = $json.choices?.[0];
let payload;
if (choice?.message?.content) {
  // En modelos JSON mode, content debe ser JSON
  try {
    payload = typeof choice.message.content === 'string'
      ? JSON.parse(choice.message.content)
      : choice.message.content;
  } catch (e) {
    payload = { etiqueta: 'Complemento_info', confianza: 0.0, explicacion: 'Parse error', claves: {} };
  }
} else if ($json.content) {
  payload = $json.content;
} else {
  payload = { etiqueta: 'Complemento_info', confianza: 0.0, explicacion: 'No content', claves: {} };
}
return [{ json: { ...$json, ia: payload } }];

// Guardrails y mapeo a etiquetas controladas
const ia = $json.ia || {};
const confianza = Number(ia.confianza ?? 0);
const etiquetaModel = (ia.etiqueta || '').toString().toLowerCase();
const map = {
  'apertura_cobertura': 'Apertura_cobertura',
  'apertura_sin_cobertura': 'Apertura_sin_cobertura',
  'complemento_info': 'Complemento_info',
  'fraude_sospecha': 'Fraude_sospecha',
  'pago_inmediato': 'Pago_inmediato',
  'derivar_peritaje': 'Derivar_peritaje',
  'derivar_legal': 'Derivar_legal'
};
let etiqueta = map[etiquetaModel] || 'Complemento_info';
let requiereRevision = false;
// Regla de umbral
if (confianza < 0.7) requiereRevision = true;
// TODO: aplica más reglas duras (fraude, cobertura, ilegible) si las tienes en $json
return [{ json: { ...$json, clasificacion: { etiqueta, subclase: ia.subclase || null, confianza, explicacion: ia.explicacion || '', claves: ia.claves || {} , requiereRevision } } }];
